{"code": "import pandas as pd
import os

# Check if data directory exists and what files are there
if os.path.exists('data'):
    files = os.listdir('data')
    print("Files in data directory:", files)
else:
    print("data directory does not exist")

# Try to read train.csv without specifying index_col to see what columns exist
try:
    train_sample = pd.read_csv('data/train.csv')
    print("\nTrain CSV columns:", train_sample.columns.tolist())
    print("\nFirst 5 rows:")
    print(train_sample.head())
except Exception as e:
    print(f"Error reading train.csv: {e}")"}

